#include <iostream>
#include <vector>

typedef double FT;
struct Point_2 {
    double x_val, y_val;
    double x() const { return x_val; }
    double y() const { return y_val; }
};

FT polygon_area(const std::vector<Point_2>& polygon) {
    if (polygon.size() < 3) return 0.0;
    FT area = 0.0;
    for (size_t i = 1; i < polygon.size() - 1; ++i) {
        area += (polygon[i].x() - polygon[0].x()) * (polygon[i+1].y() - polygon[0].y()) -
                (polygon[i+1].x() - polygon[0].x()) * (polygon[i].y() - polygon[0].y());
    }
    return area * 0.5;
}

int main() {
    std::vector<Point_2> poly = {{0,0}, {1,0}, {1,1}, {0,1}};
    std::cout << "Area: " << polygon_area(poly) << std::endl;
    return 0;
}

